INSERT INTO content_variants (id, lesson_id, variant_type, body, difficulty, is_active) VALUES
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'money-basics-101'), 'example', '{"text": "Bayu ingin beli mie ayam di warung, tapi penjualnya tidak mau menukar dengan pulpen. Bayu pakai uang Rp15.000, penjual langsung terima. Uang memudahkan pertukaran karena semua orang setuju uang punya nilai."}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'money-basics-101'), 'example', '{"text": "Saldo GoPay Rp50.000 milik Rina bisa dipakai bayar ojek online dan top-up pulsa. Meski tidak berbentuk uang kertas, saldo elektronik tetap berfungsi sebagai alat tukar karena diakui sebagai pembayaran."}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'money-basics-101'), 'explanation', '{"text": "Uang adalah alat tukar yang disepakati orang banyak. Tanpa uang, kita harus bartar—menukar barang langsung—yang sulit karena belum tentu kebutuhan kedua pihak cocok."}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'money-basics-101'), 'explanation', '{"text": "Uang punya tiga fungsi utama: alat tukar, penyimpan nilai, dan satuan hitung. GoPay, OVO, atau saldo bank termasuk uang digital karena bisa dipakai untuk ketiga fungsi tersebut."}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'money-basics-101'), 'question', '{"type": "matching", "question": "Pasangkan fungsi uang dengan contohnya.", "pairs": [["Alat tukar", "Bayar mie ayam pakai Rp15.000"], ["Penyimpan nilai", "Menabung Rp500.000 untuk beli sepatu bulan depan"], ["Satuan hitung", "Harga pulpen Rp3.000 dan buku Rp50.000"]], "answer": {"Alat tukar": "Bayar mie ayam pakai Rp15.000", "Penyimpan nilai": "Menabung Rp500.000 untuk beli sepatu bulan depan", "Satuan hitung": "Harga pulpen Rp3.000 dan buku Rp50.000"}, "explanation": "Fungsi uang membantu kita memahami mengapa uang kertas, koin, maupun saldo digital bisa dipakai dalam kehidupan sehari-hari.", "difficulty": "beginner"}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'money-basics-101'), 'question', '{"type": "true_false", "question": "Saldo GoPay atau OVO tidak termasuk uang karena tidak berbentuk uang kertas.", "answer": false, "explanation": "Saldo elektronik tetap diakui sebagai alat tukar dan satuan hitung, sehingga termasuk bentuk uang digital.", "difficulty": "beginner"}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'money-basics-101'), 'question', '{"type": "multiple_choice", "question": "Mengapa uang lebih praktis daripada barter?", "options": ["Karena uang bisa ditukar dengan barang apa saja yang dijual", "Karena uang terbuat dari logam mulia", "Karena barter lebih cepat", "Karena uang tidak bisa hilang"], "answer": "Karena uang bisa ditukar dengan barang apa saja yang dijual", "explanation": "Uang diterima umum, jadi kita tidak perlu mencari orang yang kebetulan membutuhkan barang kita.", "difficulty": "beginner"}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'money-basics-101'), 'question', '{"type": "fill_blank", "question": "Fungsi uang sebagai _____ memungkinkan kita membandingkan harga berbagai barang dengan mudah.", "answer": "satuan hitung", "explanation": "Satuan hitung membuat kita bisa menyatakan nilai barang dalam rupiah sehingga mudah membandingkan harga.", "difficulty": "beginner"}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'value-and-purchasing-power'), 'example', '{"text": "Semangkuk mie ayam di Jakarta harganya Rp18.000, tapi di kampung halaman Rina hanya Rp12.000. Uang Rp50.000 milik Rina di Jakarta cukup untuk 2 mangkuk plus sisa, di kampung cukup untuk 4 mangkuk. Daya beli uangnya berbeda di dua tempat."}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'value-and-purchasing-power'), 'example', '{"text": "Doni punya Rp100.000. Di kantin sekolah, uang itu bisa beli 10 porsi nasi goreng. Di mal, harga nasi goreng Rp35.000, jadi uangnya hanya cukup untuk 2 porsi. Lokasi dan situasi mengubah daya beli."}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'value-and-purchasing-power'), 'explanation', '{"text": "Daya beli adalah seberapa banyak barang atau jasa yang bisa dibeli dengan sejumlah uang. Uang Rp50.000 bisa jadi lebih berharga di kota kecil daripada di kota besar jika harga-harga lebih murah."}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'value-and-purchasing-power'), 'explanation', '{"text": "Nilai uang tidak hanya ditentukan oleh jumlahnya, tapi juga oleh harga barang yang ingin dibeli. Jika harga naik, daya beli turun meski nominal uang tetap sama."}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'value-and-purchasing-power'), 'question', '{"type": "multiple_choice", "question": "Mie ayam di Jakarta Rp18.000, di Yogyakarta Rp12.000. Manakah pernyataan yang benar tentang Rp50.000?", "options": ["Daya belinya lebih besar di Yogyakarta", "Daya belinya lebih besar di Jakarta", "Daya belinya sama karena nominalnya sama", "Rp50.000 tidak bisa beli mie ayam di dua kota"], "answer": "Daya belinya lebih besar di Yogyakarta", "explanation": "Dengan harga lebih murah, uang yang sama bisa membeli lebih banyak porsi, artinya daya beli lebih besar.", "difficulty": "beginner"}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'value-and-purchasing-power'), 'question', '{"type": "true_false", "question": "Jika harga barang naik, daya beli uang yang kita milai juga naik.", "answer": false, "explanation": "Ketika harga naik, uang yang sama bisa membeli lebih sedikit barang, sehingga daya beli menurun.", "difficulty": "beginner"}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'value-and-purchasing-power'), 'question', '{"type": "fill_blank", "question": "Daya beli menunjukkan seberapa _____ barang atau jasa yang bisa dibeli dengan sejumlah uang.", "answer": "banyak", "explanation": "Daya beli mengukur jumlah barang/jasa yang dapat dibeli, bukan hanya nominal uangnya.", "difficulty": "beginner"}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'value-and-purchasing-power'), 'question', '{"type": "multiple_choice", "question": "Rina punya Rp100.000. Harga novel bekas di toko online Rp25.000, di toko fisik Rp40.000. Berapa perbedaan daya beli dalam jumlah novel?", "options": ["1,5 novel lebih banyak di toko online", "Tidak ada perbedaan", "Novel lebih murah di toko fisik", "Rp100.000 tidak cukup di dua tempat"], "answer": "1,5 novel lebih banyak di toko online", "explanation": "Di toko online Rp100.000 dapat 4 novel; di toko fisik hanya 2,5 novel. Selisihnya 1,5 novel.", "difficulty": "beginner"}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'inflation-101'), 'example', '{"text": "Tahun 2020, Rina bisa membeli 10 mangkuk mie ayam dengan Rp120.000. Tahun 2025, harga mie ayam naik menjadi Rp16.000 per mangkuk, sehingga Rp120.000 hanya cukup untuk 7,5 mangkuk. Inflasi mengurangi daya beli uang yang diam saja."}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'inflation-101'), 'example', '{"text": "Ayah Doni bercerita tiket bioskop dulu Rp35.000, sekarang Rp50.000. Dengan uang Rp100.000, Doni dulu bisa nonton 2,8 kali, sekarang hanya 2 kali. Inflasi membuat harga naik secara perlahan dari tahun ke tahun."}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'inflation-101'), 'explanation', '{"text": "Inflasi adalah kenaikan harga barang dan jasa secara umum dalam periode waktu tertentu. Inflasi ringan dan stabil wajar, tetapi inflasi tinggi menggerus daya beli."}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'inflation-101'), 'explanation', '{"text": "Bank Indonesia menargetkan inflasi sekitar 2,5% plus minus 1%. Jika inflasi 4% per tahun dan tabungan kita hanya bunga 2%, nilai riil uang kita menurun."}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'inflation-101'), 'question', '{"type": "true_false", "question": "Inflasi berarti harga barang dan jasa naik secara umum dalam jangka waktu tertentu.", "answer": true, "explanation": "Inflasi adalah kenaikan harga umum yang terus-menerus, bukan kenaikan satu barang saja.", "difficulty": "beginner"}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'inflation-101'), 'question', '{"type": "true_false", "question": "Menyimpan semua uang di bawah bantal selalu aman dari inflasi.", "answer": false, "explanation": "Uang tunai tidak menghasilkan bunga, sehingga daya belinya menurun saat inflasi positif.", "difficulty": "beginner"}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'inflation-101'), 'question', '{"type": "fill_blank", "question": "Bank Indonesia menargetkan inflasi sekitar _____ persen plus minus satu persen.", "answer": "2,5", "explanation": "Target inflasi BI adalah sekitar 2,5% ± 1% untuk menjaga stabilitas ekonomi.", "difficulty": "beginner"}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'inflation-101'), 'question', '{"type": "multiple_choice", "question": "Jika inflasi 5% per tahun dan tabunganmu bunga 3% per tahun, apa yang terjadi pada daya beli tabunganmu?", "options": ["Daya beli menurun 2%", "Daya beli naik 2%", "Daya beli tetap sama", "Daya beli naik 8%"], "answer": "Daya beli menurun 2%", "explanation": "Inflasi 5% menggerus nilai uang lebih cepat daripada bunga 3% menambahnya, sehingga daya beli riil turun sekitar 2%.", "difficulty": "beginner"}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'income-vs-wealth'), 'example', '{"text": "Andi promoter gaji Rp8 juta/bulan, tapi habis untuk cicilan motor, hangout, dan belanja online. Tabungannya nol. Budi barista gaji Rp4 juta/bulan, sisihkan Rp500 ribu per bulan, dan sudah punya tabungan Rp15 juta. Budi lebih kaya karena kekayaan adalah stok yang dimiliki, bukan aliran masuk."}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'income-vs-wealth'), 'example', '{"text": "Seorang artis mendapat honor Rp100 juta per job, tetapi semua habis untuk gaya hidup mewah. Temannya guru honorer pendapatan Rp3 juta/bulan, tetapi rutin menabung dan memiliki Rp20 juta. Kekayaan dilihat dari apa yang tersisa, bukan yang masuk."}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'income-vs-wealth'), 'explanation', '{"text": "Pendapatan adalah uang yang masuk secara berkala, seperti gaji atau uang saku. Kekayaan adalah total aset yang kita miliki dikurangi utang, atau stok kepemilikan bersih."}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'income-vs-wealth'), 'explanation', '{"text": "Pendapatan tinggi tidak otomatis membuat kita kaya. Jika pengeluaran lebih besar dari pendapatan, kekayaan bisa nol atau negatif meski gaji besar."}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'income-vs-wealth'), 'question', '{"type": "matching", "question": "Pasangkan konsep dengan contohnya.", "pairs": [["Pendapatan", "Gaji Rp4 juta per bulan"], ["Kekayaan", "Tabungan Rp15 juta dikurangi utang Rp2 juta"], ["Pengeluaran", "Bayar kos Rp800 ribu per bulan"]], "answer": {"Pendapatan": "Gaji Rp4 juta per bulan", "Kekayaan": "Tabungan Rp15 juta dikurangi utang Rp2 juta", "Pengeluaran": "Bayar kos Rp800 ribu per bulan"}, "explanation": "Membedakan aliran uang (pendapatan/pengeluaran) dan stok kepemilikan (kekayaan) membantu kita menilai kesehatan keuangan.", "difficulty": "beginner"}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'income-vs-wealth'), 'question', '{"type": "multiple_choice", "question": "Andi gaji Rp8 juta, tabungan nol. Budi gaji Rp4 juta, tabungan Rp15 juta. Siapa yang lebih kaya?", "options": ["Budi", "Andi", "Sama kaya", "Tidak bisa dibandingkan"], "answer": "Budi", "explanation": "Kekayaan diukur dari aset bersih yang dimiliki, bukan dari besarnya gaji.", "difficulty": "beginner"}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'income-vs-wealth'), 'question', '{"type": "true_false", "question": "Pendapatan tinggi selalu berarti kekayaan tinggi.", "answer": false, "explanation": "Jika pengeluaran lebih besar dari pendapatan, orang dengan gaji tinggi bisa memiliki kekayaan rendah atau bahkan utang.", "difficulty": "beginner"}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'income-vs-wealth'), 'question', '{"type": "fill_blank", "question": "Kekayaan bersih dihitung dari total aset dikurangi total _____.", "answer": "utang", "explanation": "Kekayaan bersih = aset - utang. Ini menunjukkan seberapa besar harta yang benar-benar kita miliki.", "difficulty": "beginner"}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'needs-vs-wants-101'), 'example', '{"text": "Sari menerima uang saku Rp1.500.000 per bulan. Kos Rp700.000, pulsa dan kuota Rp150.000, makan di kantin Rp400.000 adalah kebutuhan. Langganan streaming Rp50.000 dan sepatu baru Rp300.000 adalah keinginan. Jika uang saku habis, kebutuhan harus didahulukan."}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'needs-vs-wants-101'), 'example', '{"text": "Doni ingin membeli headphone baru Rp800.000, padahal headphone lamanya masih berfungsi. Di sisi lain, uangnya hanya Rp1 juta dan ia belum bayar uang kos Rp700.000. Headphone adalah keinginan, kos adalah kebutuhan."}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'needs-vs-wants-101'), 'explanation', '{"text": "Kebutuhan adalah hal penting untuk hidup dan belajar, seperti makan, tempat tinggal, transportasi, dan pulsa. Keinginan adalah hal yang menyenangkan tetapi tidak mendesak."}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'needs-vs-wants-101'), 'explanation', '{"text": "Membedakan kebutuhan dan keinginan membantu kita menyusun anggaran. Aturan sederhana: bayar kebutuhan terlebih dahulu, baru alokasikan sisa untuk keinginan dan tabungan."}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'needs-vs-wants-101'), 'question', '{"type": "ordering", "question": "Urutkan pengeluaran Sari dari yang paling mendesak (kebutuhan) hingga paling bisa ditunda (keinginan).", "options": ["Bayar kos", "Beli pulsa dan kuota", "Langganan streaming", "Beli sepatu baru"], "answer": ["Bayar kos", "Beli pulsa dan kuota", "Langganan streaming", "Beli sepatu baru"], "explanation": "Kos dan pulsa adalah kebutuhan dasar. Streaming dan sepatu baru adalah keinginan yang bisa ditunda.", "difficulty": "beginner"}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'needs-vs-wants-101'), 'question', '{"type": "multiple_choice", "question": "Manakah yang termasuk kebutuhan bagi pelajar?", "options": ["Pulsa dan kuota internet untuk tugas", "Tiket konser", "Skin game terbaru", "Kopi kekinian setiap hari"], "answer": "Pulsa dan kuota internet untuk tugas", "explanation": "Pulsa dan kuota mendukung aktivitas belajar, sehingga termasuk kebutuhan.", "difficulty": "beginner"}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'needs-vs-wants-101'), 'question', '{"type": "true_false", "question": "Keinginan harus selalu dipenuhi terlebih dahulu agar hidup bahagia.", "answer": false, "explanation": "Kebutuhan dasar harus didahulukan. Keinginan baru dipertimbangkan setelah kebutuhan dan tabungan tercukupi.", "difficulty": "beginner"}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'needs-vs-wants-101'), 'question', '{"type": "fill_blank", "question": "Makan siang di kantin termasuk _____, sedangkan makan di kafe mahal setiap hari termasuk keinginan.", "answer": "kebutuhan", "explanation": "Makan untuk bertahan hidup dan belajar adalah kebutuhan, tetapi pilihan tempat mewah adalah keinginan.", "difficulty": "beginner"}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'assets-vs-liabilities'), 'example', '{"text": "Dodi membeli motor kredit untuk jadi driver ojek online. Motor itu menghasilkan uang setiap hari dari orderan, meski ia masih bayar cicilan. Bagi Dodi, motor itu aset karena memasukkan uang ke kantongnya."}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'assets-vs-liabilities'), 'example', '{"text": "Eko membeli motor kredit yang sama hanya untuk jalan-jalan akhir pekan. Ia bayar cicilan, bensin, dan parkir, tapi motor tidak menghasilkan uang. Bagi Eko, motor itu lebih bersifat liabilitas karena mengeluarkan uang terus."}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'assets-vs-liabilities'), 'explanation', '{"text": "Aset adalah sesuatu yang memasukkan uang ke kantong kita atau bisa meningkat nilainya. Liabilitas adalah sesuatu yang mengeluarkan uang dari kantong kita."}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'assets-vs-liabilities'), 'explanation', '{"text": "Barang yang sama bisa jadi aset atau liabilitas tergantung cara menggunakannya. Motor untuk kerja bisa jadi aset, motor hanya untuk gaya bisa jadi liabilitas."}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'assets-vs-liabilities'), 'question', '{"type": "matching", "question": "Pasangkan item dengan kategorinya.", "pairs": [["Aset", "Deposito yang menghasilkan bunga"], ["Liabilitas", "Cicilan motor hanya untuk gaya"], ["Bisa keduanya", "Motorbike yang dipakai kerja dan jalan-jalan"]], "answer": {"Aset": "Deposito yang menghasilkan bunga", "Liabilitas": "Cicilan motor hanya untuk gaya", "Bisa keduanya": "Motorbike yang dipakai kerja dan jalan-jalan"}, "explanation": "Kategori tergantung pada apakah item tersebut memasukkan atau mengeluarkan uang.", "difficulty": "beginner"}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'assets-vs-liabilities'), 'question', '{"type": "multiple_choice", "question": "Dodi membeli motor untuk jadi ojek online. Eko membeli motor serupa hanya untuk jalan-jalan. Siapa yang lebih mungkin memiliki aset?", "options": ["Dodi", "Eko", "Keduanya sama", "Tidak ada yang benar"], "answer": "Dodi", "explanation": "Motor Dodi menghasilkan pendapatan, sehingga bersifat aset. Motor Eko hanya mengeluarkan biaya.", "difficulty": "beginner"}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'assets-vs-liabilities'), 'question', '{"type": "true_false", "question": "Aset selalu berbentuk barang fisik seperti rumah atau mobil.", "answer": false, "explanation": "Aset bisa berupa uang tunai, deposito, saham, keterampilan, atau bisnis yang menghasilkan uang.", "difficulty": "beginner"}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'assets-vs-liabilities'), 'question', '{"type": "fill_blank", "question": "Jika suatu barang mengeluarkan uang terus-menerus tanpa menghasilkan pendapatan, barang itu lebih bersifat _____.", "answer": "liabilitas", "explanation": "Liabilitas menguras uang, seperti cicilan barang konsumtif yang tidak menghasilkan pendapatan.", "difficulty": "beginner"}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'understanding-risk'), 'example', '{"text": "Rina meminjamkan Rp200.000 kepada teman yang sering terlambat bayar. Risikonya adalah temannya tidak membayar kembali. Imbalannya adalah temannya bisa lekas menyelesaikan masalah dan Rina mendapat reputasi sebagai teman yang membantu."}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'understanding-risk'), 'example', '{"text": "Doni memilih naik ojek online saat hujan deras. Risikonya adalah perjalanan lebih lama dan mahal. Imbalannya adalah ia sampai di rumah lebih cepat dan lebih aman daripada naik motor sendiri."}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'understanding-risk'), 'explanation', '{"text": "Risiko adalah kemungkinan hasil yang terjadi lebih buruk dari yang diharapkan. Semua pilihan memiliki risiko, termasuk menyimpan uang di bantal yang berisiko hilang atau inflasi."}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'understanding-risk'), 'explanation', '{"text": "Mengelola risiko bukan berarti menghindari risiko sepenuhnya. Kita mengenali risiko, memutuskan apakah imbalannya sepadan, lalu mengambil langkah pengamanan jika perlu."}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'understanding-risk'), 'question', '{"type": "case_study", "question": "Baca kasus berikut dan pilih respons terbaik.", "caseText": "Rina diminta meminjamkan Rp500.000 kepada teman yang baru beberapa kali bertemu. Teman itu berjanji membayar minggu depan, tetapi Rina mendengar dia sering menunda hutang.", "followUp": {"question": "Apa risiko utama yang dihadapi Rina?", "options": ["Teman tidak membayar kembali", "Rina kehilangan waktu", "Rina kehilangan kesempatan memakai uang itu", "Teman meminjam lagi"], "answer": "Teman tidak membayar kembali", "explanation": "Risiko kredit adalah lawan tidak memenuhi janji pembayaran."}, "answer": "Risiko utama adalah uangnya tidak kembali. Rina bisa meminimalkan risiko dengan meminjam dalam jumlah kecil atau meminta jaminan.", "explanation": "Risiko adalah kemungkinan hasil buruk. Meminjamkan uang kepada seseorang yang sering menunda berarti risiko gagal bayar tinggi.", "difficulty": "beginner"}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'understanding-risk'), 'question', '{"type": "true_false", "question": "Risiko hanya ada dalam investasi, tidak ada dalam kehidupan sehari-hari.", "answer": false, "explanation": "Risiko ada di mana saja: meminjamkan uang, naik kendaraan, memilih jurusan, bahkan menyimpan uang di rumah.", "difficulty": "beginner"}'::jsonb, 'beginner', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'understanding-risk'), 'question', '{"type": "multiple_choice", "question": "Manakah contoh risiko dalam kehidupan sehari-hari?", "options": ["Meminjamkan uang tanpa jaminan", "Menyimpan uang di bank berlisensi", "Membeli pulsa di konter resmi", "Membayar uang kos tepat waktu"], "answer": "Meminjamkan uang tanpa jaminan", "explanation": "Meminjamkan uang tanpa jaminan berisiko lawan tidak membayar kembali.", "difficulty": "beginner"}'::jsonb, 'beginner', TRUE),
