  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'compound-interest-101'), 'question', '{"type": "multiple_choice", "question": "Tabungan Rp1.000.000 dengan bunga 5% per tahun. Setelah tahun pertama saldo Rp1.050.000. Berapa bunga tahun kedua?", "options": ["Rp52.500", "Rp50.000", "Rp5.000", "Rp100.000"], "answer": "Rp52.500", "explanation": "5% dari Rp1.050.000 adalah Rp52.500.", "difficulty": "intermediate"}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'bank-vs-investment'), 'example', '{"text": "Bayu punya Rp5.000.000. Ia perlu Rp2.000.000 bulan depan untuk uang kuliah. Rp2 juta itu disimpan di tabungan agar mudah diambil. Rp3.000.000 yang tidak segera dipakai bisa diputar di deposito atau reksa dana sesuai tujuan."}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'bank-vs-investment'), 'example', '{"text": "Rina ingin membeli rumah 10 tahun lagi. Tabungan bank dengan bunga 3% mungkin tidak cukup mengimbangi inflasi. Investasi seperti reksa dana saham berisiko lebih tinggi tetapi berpotensi memberi imbal hasil lebih besar untuk tujuan jangka panjang."}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'bank-vs-investment'), 'explanation', '{"text": "Bank (tabungan/deposito) umumnya aman dan likuid, cocok untuk dana darurat dan tujuan jangka pendek. Investasi berpotensi imbal hasil lebih tinggi tetapi memiliki risiko dan cocok untuk jangka panjang."}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'bank-vs-investment'), 'explanation', '{"text": "Pilih bank untuk uang yang akan segera dipakai. Pilih investasi untuk uang yang bisa dibiarkan tumbuh dalam jangka waktu lama."}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'bank-vs-investment'), 'question', '{"type": "matching", "question": "Pasangkan tujuan keuangan dengan tempat yang paling cocok.", "pairs": [["Dana darurat", "Tabungan bank"], ["Tujuan 1 tahun", "Deposito"], ["Tujuan 10 tahun", "Reksa dana saham"]], "answer": {"Dana darurat": "Tabungan bank", "Tujuan 1 tahun": "Deposito", "Tujuan 10 tahun": "Reksa dana saham"}, "explanation": "Pemilihan instrumen tergantung pada waktu dan risiko yang bisa ditoleransi.", "difficulty": "intermediate"}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'bank-vs-investment'), 'question', '{"type": "multiple_choice", "question": "Bayu butuh Rp2 juta bulan depan untuk uang kuliah. Tempat terbaik untuk menyimpannya adalah ...", "options": ["Tabungan bank", "Saham individu", "Kripto", "Reksa dana saham"], "answer": "Tabungan bank", "explanation": "Uang yang segera dibutuhkan harus aman dan likuid, seperti tabungan bank.", "difficulty": "intermediate"}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'bank-vs-investment'), 'question', '{"type": "true_false", "question": "Investasi selalu lebih baik daripada menyimpan uang di bank untuk semua tujuan.", "answer": false, "explanation": "Investasi memiliki risiko. Untuk tujuan jangka pendek dan dana darurat, bank lebih aman.", "difficulty": "intermediate"}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'bank-vs-investment'), 'question', '{"type": "fill_blank", "question": "Untuk tujuan jangka panjang, investasi berpotensi memberi imbal hasil lebih tinggi tetapi juga memiliki _____ lebih tinggi.", "answer": "risiko", "explanation": "Imbal hasil lebih tinggi umumnya disertai risiko lebih tinggi.", "difficulty": "intermediate"}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'risk-return-101'), 'example', '{"text": "Tabungan bank menawarkan bunga rendah sekitar 2-4% per tahun, tetapi uang relatif aman. Reksa dana saham berpotensi imbal hasil lebih tinggi, tetapi nilainya bisa turun dalam jangka pendek. Ini adalah hubungan risiko dan imbal hasil."}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'risk-return-101'), 'example', '{"text": "Obligasi pemerintah umumnya lebih aman daripada saham perusahaan kecil. Oleh karena itu, imbal hasil obligasi pemerintah biasanya lebih rendah dari potensi saham."}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'risk-return-101'), 'explanation', '{"text": "Secara umum, semakin tinggi potensi imbal hasil, semakin tinggi risiko yang harus diterima. Tidak ada investasi yang menghasilkan tinggi tanpa risiko."}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'risk-return-101'), 'explanation', '{"text": "Pilihan investasi harus disesuaikan dengan tujuan dan toleransi risiko. Dana darurat tidak boleh diinvestasikan secara agresif."}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'risk-return-101'), 'question', '{"type": "multiple_choice", "question": "Manakah pernyataan yang benar tentang hubungan risiko dan imbal hasil?", "options": ["Imbal hasil tinggi biasanya disertai risiko tinggi", "Investasi aman selalu menghasilkan untung besar", "Risiko tinggi berarti pasti rugi", "Imbal hasil dan risiko tidak berhubungan"], "answer": "Imbal hasil tinggi biasanya disertai risiko tinggi", "explanation": "Investor menuntut kompensasi lebih besar untuk menanggung risiko lebih besar.", "difficulty": "intermediate"}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'risk-return-101'), 'question', '{"type": "true_false", "question": "Tabungan bank berisiko sangat rendah, sehingga bunganya biasanya rendah.", "answer": true, "explanation": "Risiko rendah umumnya diimbangi dengan imbal hasil rendah.", "difficulty": "intermediate"}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'risk-return-101'), 'question', '{"type": "fill_blank", "question": "Reksa dana saham memiliki potensi imbal hasil tinggi tetapi juga _____ harga yang lebih besar.", "answer": "fluktuasi", "explanation": "Saham bisa naik dan turun dalam jangka pendek, sehingga risiko fluktuasi tinggi.", "difficulty": "intermediate"}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'risk-return-101'), 'question', '{"type": "multiple_choice", "question": "Untuk tujuan 5 tahun ke depan, mana yang lebih sesuai?", "options": ["Reksa dana saham dibanding tabungan", "Tabungan 100%", "Menyimpan uang tunai", "Pinjaman online"], "answer": "Reksa dana saham dibanding tabungan", "explanation": "Untuk jangka menengah-panjang, investasi seperti reksa dana saham lebih berpotensi mengalahkan inflasi.", "difficulty": "intermediate"}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'diversification-101'), 'example', '{"text": "Warung A hanya menjual mie ayam. Ketika harga ayam melonjak, penjualan anjlok. Warung B menjual mie ayam, es teh, nasi goreng, dan gorengan. Jika satu menu rugi, menu lain tetap mendatangkan uang. Warung B lebih terdiversifikasi."}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'diversification-101'), 'example', '{"text": "Rina memiliki uang Rp10.000.000. Jika semuanya disimpan dalam satu saham perusahaan kecil dan perusahaan itu bangkrut, uangnya hilang. Jika ia membeli reksa dana yang berisi banyak saham, kerugian satu saham tidak menghancurkan seluruh investasi."}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'diversification-101'), 'explanation', '{"text": "Diversifikasi adalah menyebarkan uang ke berbagai aset agar kerugian satu aset tidak terlalu berdampak besar pada keseluruhan."}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'diversification-101'), 'explanation', '{"text": "Diversifikasi mengurangi risiko tanpa harus memprediksi aset mana yang terbaik. Itu sebabnya diversifikasi sering disebut ''makan siang gratis'' dalam investasi."}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'diversification-101'), 'question', '{"type": "case_study", "question": "Baca kasus berikut dan pilih respons terbaik.", "caseText": "Andi punya Rp5.000.000 dan ingin mulai investasi. Temannya menyarankan membeli saham satu perusahaan teknologi karena sedang viral. Andi ingin aman tetapi tetap berpotensi tumbuh.", "followUp": {"question": "Apa saran terbaik untuk Andi?", "options": ["Pilih reksa dana yang memiliki banyak saham agar terdiversifikasi", "Beli semua saham perusahaan viral", "Tunggu sampai punya Rp50 juta", "Pinjam uang untuk beli lebih banyak saham viral"], "answer": "Pilih reksa dana yang memiliki banyak saham agar terdiversifikasi", "explanation": "Reksa dana menyebarkan risiko ke banyak saham, sehingga kerugian satu saham tidak terlalu besar."}, "answer": "Diversifikasi melindungi Andi dari risiko saham tunggal.", "explanation": "Diversifikasi mengurangi risiko tanpa harus memilih satu pemenang. Reksa dana adalah cara sederhana untuk diversifikasi.", "difficulty": "intermediate"}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'diversification-101'), 'question', '{"type": "multiple_choice", "question": "Manakah manfaat diversifikasi?", "options": ["Mengurangi dampak kerugian satu aset", "Menjamin keuntungan setiap tahun", "Menghilangkan risiko sepenuhnya", "Membuat investasi lebih rumit"], "answer": "Mengurangi dampak kerugian satu aset", "explanation": "Diversifikasi menyebarkan risiko, tetapi tidak menghilangkan risiko atau menjamin keuntungan.", "difficulty": "intermediate"}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'diversification-101'), 'question', '{"type": "true_false", "question": "Diversifikasi menjamin investasi selalu menghasilkan keuntungan.", "answer": false, "explanation": "Diversifikasi mengurangi risiko, tetapi tidak menjamin keuntungan.", "difficulty": "intermediate"}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'diversification-101'), 'question', '{"type": "fill_blank", "question": "Diversifikasi sering disebut ''makan siang gratis'' karena mengurangi risiko tanpa harus _____ aset mana yang terbaik.", "answer": "menebak", "explanation": "Dengan diversifikasi, kita tidak perlu memprediksi pemenang; kita memiliki banyak aset.", "difficulty": "intermediate"}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'reksa-dana-basics'), 'example', '{"text": "Ani ingin berinvestasi di saham tetapi tidak tahu cara memilih perusahaan. Ia membeli reksa dana saham yang dikelola manajer investasi berizin OJK. Uangnya digabung dengan uang banyak investor lain untuk membeli banyak saham sekaligus."}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'reksa-dana-basics'), 'example', '{"text": "Reksa dana pasar uang berisiko rendah dan cocok untuk jangka pendek. Reksa dana pendapatan tetap menengah. Reksa dana saham berpotensi imbal hasil tinggi tetapi berfluktuasi besar."}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'reksa-dana-basics'), 'explanation', '{"text": "Reksa dana adalah wadah untuk mengumpulkan uang dari banyak investor, lalu dikelola manajer investasi untuk dibeli berbagai aset sesuai jenis reksa dana."}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'reksa-dana-basics'), 'explanation', '{"text": "Jenis utama: pasar uang (rendah risiko), pendapatan tetap (menengah), saham (tinggi risiko/imbal hasil). Pilihlah sesuai tujuan dan waktu."}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'reksa-dana-basics'), 'question', '{"type": "matching", "question": "Pasangkan jenis reksa dana dengan karakteristiknya.", "pairs": [["Reksa dana pasar uang", "Rendah risiko, cocok jangka pendek"], ["Reksa dana pendapatan tetap", "Risiko menengah, berisi obligasi"], ["Reksa dana saham", "Risiko tinggi, potensi imbal hasil tinggi"]], "answer": {"Reksa dana pasar uang": "Rendah risiko, cocok jangka pendek", "Reksa dana pendapatan tetap": "Risiko menengah, berisi obligasi", "Reksa dana saham": "Risiko tinggi, potensi imbal hasil tinggi"}, "explanation": "Setiap jenis reksa dana memiliki profil risiko dan imbal hasil yang berbeda.", "difficulty": "intermediate"}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'reksa-dana-basics'), 'question', '{"type": "multiple_choice", "question": "Mengapa reksa dana cocok untuk pemula seperti Ani?", "options": ["Karena uangnya dikelola profesional dan terdiversifikasi", "Karena dijamin untung oleh pemerintah", "Karena tidak ada risiko", "Karena hanya butuh Rp10.000"], "answer": "Karena uangnya dikelola profesional dan terdiversifikasi", "explanation": "Reksa dana memungkinkan pemula memiliki banyak aset sekaligus dengan pengelolaan profesional.", "difficulty": "intermediate"}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'reksa-dana-basics'), 'question', '{"type": "true_false", "question": "Semua jenis reksa dana memiliki risiko yang sama.", "answer": false, "explanation": "Reksa dana pasar uang, pendapatan tetap, dan saham memiliki profil risiko berbeda.", "difficulty": "intermediate"}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'reksa-dana-basics'), 'question', '{"type": "fill_blank", "question": "Reksa dana dikelola oleh _____ investasi yang berizin OJK.", "answer": "manajer", "explanation": "Manajer investasi mengelola dana investor sesuai prospektus reksa dana.", "difficulty": "intermediate"}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'what-is-a-stock'), 'example', '{"text": "Membeli 1 lot saham BBCA artinya membeli 100 lembar saham Bank Central Asia. Dengan membeli saham, kita menjadi pemilik sebagian kecil bank tersebut. Jika bank untung, nilai saham bisa naik; jika rugi, bisa turun."}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'what-is-a-stock'), 'example', '{"text": "Harga saham GOTO berubah setiap hari karena banyak orang membeli dan menjual. Jika lebih banyak yang ingin membeli, harga naik. Jika lebih banyak yang ingin menjual, harga turun."}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'what-is-a-stock'), 'explanation', '{"text": "Saham adalah bukti kepemilikan sebagian dari perusahaan. Harga saham berubah karena permintaan dan penawaran di pasar."}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'what-is-a-stock'), 'explanation', '{"text": "Membeli saham berbeda dengan meminjamkan uang. Saham = kepemilikan. Obligasi = pinjaman."}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'what-is-a-stock'), 'question', '{"type": "multiple_choice", "question": "Apa artinya membeli saham perusahaan?", "options": ["Menjadi pemilik sebagian kecil perusahaan", "Meminjamkan uang kepada perusahaan", "Menjadi karyawan perusahaan", "Mendapat gaji tetap dari perusahaan"], "answer": "Menjadi pemilik sebagian kecil perusahaan", "explanation": "Saham adalah bukti kepemilikan sebagian dari perusahaan.", "difficulty": "intermediate"}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'what-is-a-stock'), 'question', '{"type": "true_false", "question": "Harga saham naik jika lebih banyak orang yang ingin membeli daripada menjual.", "answer": true, "explanation": "Harga ditentukan oleh permintaan dan penawaran. Permintaan tinggi mendorong harga naik.", "difficulty": "intermediate"}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'what-is-a-stock'), 'question', '{"type": "fill_blank", "question": "Jika membeli 1 lot saham BBCA, kita memiliki _____ lembar saham.", "answer": "100", "explanation": "Di IDX, 1 lot sama dengan 100 lembar saham.", "difficulty": "intermediate"}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'what-is-a-stock'), 'question', '{"type": "multiple_choice", "question": "Saham berbeda dengan obligasi karena ...", "options": ["Saham adalah kepemilikan, obligasi adalah pinjaman", "Saham lebih aman dari obligasi", "Obligasi adalah kepemilikan", "Keduanya sama"], "answer": "Saham adalah kepemilikan, obligasi adalah pinjaman", "explanation": "Pemegang saham memiliki perusahaan; pemegang obligasi meminjamkan uang kepada perusahaan.", "difficulty": "intermediate"}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'idx-basics-101'), 'example', '{"text": "Doni ingin membeli 75 lembar saham TLKM. Di Bursa Efek Indonesia, saham diperdagangkan dalam lot yang terdiri dari 100 lembar. Doni harus membeli minimal 1 lot atau 100 lembar."}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'idx-basics-101'), 'example', '{"text": "Perdagangan saham di IDX berlangsung hari kerja, Senin-Jumat. Jika Doni ingin membeli saham, ia harus memiliki rekening efek di perusahaan sekuritas yang terdaftar."}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'idx-basics-101'), 'explanation', '{"text": "IDX adalah Bursa Efek Indonesia. Di IDX, 1 lot = 100 lembar saham. Perdagangan hari kerja dengan jam tertentu."}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'idx-basics-101'), 'explanation', '{"text": "SIPF (Securities Investor Protection Fund) memberikan perlindungan bagi investor di pasar modal sesuai ketentuan. Ini adalah salah satu mekanisme perlindungan investor."}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'idx-basics-101'), 'question', '{"type": "fill_blank", "question": "Di IDX, 1 lot saham sama dengan _____ lembar saham.", "answer": "100", "explanation": "1 lot di Bursa Efek Indonesia terdiri dari 100 lembar saham.", "difficulty": "intermediate"}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'idx-basics-101'), 'question', '{"type": "multiple_choice", "question": "Doni ingin membeli 75 lembar saham TLKM. Apa yang harus ia lakukan?", "options": ["Membeli minimal 1 lot (100 lembar)", "Membeli tepat 75 lembar", "Menjual 25 lembar", "Meminjam saham dari broker"], "answer": "Membeli minimal 1 lot (100 lembar)", "explanation": "IDX menggunakan satuan lot, minimal 1 lot = 100 lembar.", "difficulty": "intermediate"}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'idx-basics-101'), 'question', '{"type": "true_false", "question": "SIPF memberikan perlindungan bagi investor di pasar modal Indonesia.", "answer": true, "explanation": "SIPF adalah mekanisme perlindungan investor di pasar modal sesuai ketentuan.", "difficulty": "intermediate"}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'idx-basics-101'), 'question', '{"type": "multiple_choice", "question": "Berapa lot minimal yang bisa dibeli untuk satu saham di IDX?", "options": ["1 lot", "0,5 lot", "10 lot", "Tidak ada minimum"], "answer": "1 lot", "explanation": "Di IDX, pembelian saham minimal 1 lot yang berisi 100 lembar.", "difficulty": "intermediate"}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'reading-a-stock-page'), 'example', '{"text": "Saham BBCA hari ini dibuka di Rp8.450, tertinggi Rp8.620, terendah Rp8.400, dan ditutup di Rp8.550. Volume 45 juta lembar. Open, high, low, close menunjukkan rentang harga, sedangkan volume menunjukkan seberapa aktif saham diperdagangkan."}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'reading-a-stock-page'), 'example', '{"text": "Market cap menunjukkan nilai total perusahaan. Jika harga saham Rp1.000 dan ada 10 miliar lembar saham, market cap-nya Rp10 triliun. Volume tinggi artinya banyak transaksi."}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'reading-a-stock-page'), 'explanation', '{"text": "Open adalah harga pembukaan, high/low adalah harga tertinggi/terendah, close adalah harga penutupan, volume adalah jumlah saham yang diperdagangkan, dan market cap adalah nilai pasar perusahaan."}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'reading-a-stock-page'), 'explanation', '{"text": "Volume menunjukkan likuiditas. Saham dengan volume tinggi lebih mudah dibeli dan dijual tanpa menggerakkan harga terlalu banyak."}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'reading-a-stock-page'), 'question', '{"type": "matching", "question": "Pasangkan istilah saham dengan artinya.", "pairs": [["Open", "Harga saham saat pasar dibuka"], ["High", "Harga tertinggi hari itu"], ["Volume", "Jumlah saham yang diperdagangkan"], ["Market cap", "Nilai total perusahaan di pasar"]], "answer": {"Open": "Harga saham saat pasar dibuka", "High": "Harga tertinggi hari itu", "Volume": "Jumlah saham yang diperdagangkan", "Market cap": "Nilai total perusahaan di pasar"}, "explanation": "Memahami istilah dasar membaca halaman saham sangat penting sebelum berinvestasi.", "difficulty": "intermediate"}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'reading-a-stock-page'), 'question', '{"type": "multiple_choice", "question": "Saham ABC dibuka Rp1.000, high Rp1.100, low Rp950, close Rp1.050. Berapa rentang harga hari itu?", "options": ["Rp950 - Rp1.100", "Rp1.000 - Rp1.050", "Rp1.050 - Rp1.100", "Rp950 - Rp1.050"], "answer": "Rp950 - Rp1.100", "explanation": "Rentang harga adalah dari low (terendah) ke high (tertinggi), yaitu Rp950 hingga Rp1.100.", "difficulty": "intermediate"}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'reading-a-stock-page'), 'question', '{"type": "true_false", "question": "Volume saham yang tinggi berarti saham tersebut pasti menguntungkan.", "answer": false, "explanation": "Volume tinggi hanya menunjukkan aktivitas perdagangan tinggi, bukan jaminan keuntungan.", "difficulty": "intermediate"}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'reading-a-stock-page'), 'question', '{"type": "fill_blank", "question": "Harga penutupan saham disebut _____.", "answer": "close", "explanation": "Close adalah harga terakhir saham diperdagangkan pada hari itu.", "difficulty": "intermediate"}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'portfolio-thinking'), 'example', '{"text": "Rina memiliki Rp10.000.000: Rp3 juta di tabungan, Rp4 juta di reksa dana pasar uang, dan Rp3 juta di satu saham. Ini adalah portofolio, meskipun masih perlu diversifikasi lebih baik."}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'portfolio-thinking'), 'example', '{"text": "Jika tujuan Rina membeli laptop dalam 1 tahun, sebagian besar dananya harus aman. Jika tujuannya pensiun 30 tahun lagi, ia bisa menambah saham dan reksa dana saham."}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'portfolio-thinking'), 'explanation', '{"text": "Portofolio adalah gabungan semua aset yang kita miliki. Memikirkan portofolio berarti mempertimbangkan keseluruhan, bukan hanya satu aset."}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'portfolio-thinking'), 'explanation', '{"text": "Komposisi portofolio harus sesuai dengan tujuan dan horizon waktu. Tujuan jangka pendek perlu aset aman; tujuan jangka panjang bisa menahan fluktuasi."}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'portfolio-thinking'), 'question', '{"type": "case_study", "question": "Baca kasus berikut dan pilih respons terbaik.", "caseText": "Rina berusia 19 tahun, ingin pensiun di usia 50 tahun. Saat ini ia menempatkan 100% uangnya di tabungan dengan bunga 3%. Inflasi rata-rata 4%.", "followUp": {"question": "Apa masalah utama portofolio Rina?", "options": ["Tabungan tidak mengimbangi inflasi untuk tujuan jangka panjang", "Tabungan terlalu berisiko", "Tabungan sudah cukup untuk tujuan jangka panjang", "Inflasi tidak berpengaruh pada tabungan"], "answer": "Tabungan tidak mengimbangi inflasi untuk tujuan jangka panjang", "explanation": "Untuk tujuan jangka panjang, tabungan dengan bunga rendah bisa kehilangan daya beli karena inflasi."}, "answer": "Portofolio Rina terlalu konservatif untuk horizon waktu panjang.", "explanation": "Portofolio harus disesuaikan dengan tujuan dan waktu. Untuk pensiun jangka panjang, perlu aset yang berpotensi tumbuh lebih tinggi.", "difficulty": "intermediate"}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'portfolio-thinking'), 'question', '{"type": "multiple_choice", "question": "Apa yang dimaksud dengan portofolio?", "options": ["Gabungan semua aset yang dimiliki", "Satu saham yang paling bagus", "Tabungan di satu bank", "Utang yang dimiliki"], "answer": "Gabungan semua aset yang dimiliki", "explanation": "Portofolio mencakup tabungan, deposito, saham, reksa dana, dan aset lain yang kita miliki.", "difficulty": "intermediate"}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'portfolio-thinking'), 'question', '{"type": "true_false", "question": "Komposisi portofolio harus sama untuk semua orang regardless tujuan keuangan.", "answer": false, "explanation": "Portofolio harus disesuaikan dengan tujuan, horizon waktu, dan toleransi risiko masing-masing.", "difficulty": "intermediate"}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'portfolio-thinking'), 'question', '{"type": "fill_blank", "question": "Untuk tujuan jangka panjang, portofolio bisa memiliki lebih banyak aset yang berpotensi tumbuh meski lebih _____.", "answer": "berisiko", "explanation": "Waktu panjang memungkinkan kita menahan fluktuasi aset berisiko untuk potensi imbal hasil lebih tinggi.", "difficulty": "intermediate"}'::jsonb, 'intermediate', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'taxes-on-returns'), 'example', '{"text": "Doni mendapat bunga deposito Rp500.000 dan dividen saham Rp1.000.000. Pemerintah mengenakan pajak atas penghasilan tersebut. Setelah pajak, uang yang benar-benar ia terima lebih kecil dari angka kotor."}'::jsonb, 'advanced', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'taxes-on-returns'), 'example', '{"text": "Sebuah reksa dana mengiklankan imbal hasil 10% per tahun. Setelah pajak final atas bunga atau dividen, imbal hasil bersih yang diterima investor bisa lebih rendah, misalnya 8,5%."}'::jsonb, 'advanced', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'taxes-on-returns'), 'explanation', '{"text": "Pajak atas imbal hasil investasi mengurangi keuntungan bersih yang kita terima. Oleh karena itu, bandingkan imbal hasil bersih, bukan hanya angka kotor."}'::jsonb, 'advanced', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'taxes-on-returns'), 'explanation', '{"text": "Jenis imbal hasil yang bisa kena pajak di Indonesia antara lain bunga deposito, dividen, dan capital gain sesuai ketentuan perpajakan yang berlaku."}'::jsonb, 'advanced', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'taxes-on-returns'), 'question', '{"type": "multiple_choice", "question": "Mengapa penting memperhitungkan pajak saat membandingkan imbal hasil?", "options": ["Karena pajak mengurangi imbal hasil bersih", "Karena pajak menambah imbal hasil", "Karena pajak hanya untuk perusahaan", "Karena pajak tidak berlaku untuk investor kecil"], "answer": "Karena pajak mengurangi imbal hasil bersih", "explanation": "Imbal hasil kotor bisa lebih tinggi dari imbal hasil bersih setelah pajak.", "difficulty": "advanced"}'::jsonb, 'advanced', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'taxes-on-returns'), 'question', '{"type": "true_false", "question": "Imbal hasil yang diiklankan produk investasi sudah pasti sama dengan yang diterima investor.", "answer": false, "explanation": "Imbal hasil kotor belum memperhitungkan pajak, biaya, dan potensi perubahan harga.", "difficulty": "advanced"}'::jsonb, 'advanced', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'taxes-on-returns'), 'question', '{"type": "fill_blank", "question": "Pendapatan dari dividen dan bunga deposito bisa dikenakan _____ sesuai ketentuan.", "answer": "pajak", "explanation": "Pemerintah mengenakan pajak atas beberapa jenis imbal hasil investasi.", "difficulty": "advanced"}'::jsonb, 'advanced', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'taxes-on-returns'), 'question', '{"type": "multiple_choice", "question": "Doni mendapat dividen kotor Rp1.000.000 dan pajak 10%. Berapa dividen bersihnya?", "options": ["Rp900.000", "Rp1.100.000", "Rp800.000", "Rp1.000.000"], "answer": "Rp900.000", "explanation": "Pajak 10% dari Rp1.000.000 adalah Rp100.000, sehingga bersihnya Rp900.000.", "difficulty": "advanced"}'::jsonb, 'advanced', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'macro-indicators'), 'example', '{"text": "Bank Indonesia menaikkan BI Rate. Bunga deposito bank bisa naik, sehingga menabung lebih menguntungkan. Namun, biaya pinjaman juga naik dan harga saham bisa lebih volatile. Indikator makro ini memengaruhi keputusan keuangan."}'::jsonb, 'advanced', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'macro-indicators'), 'example', '{"text": "Ketika nilai tukar rupiah melemah terhadap dolar AS, harga gadget impor seperti smartphone atau laptop bisa naik. Inflasi yang tinggi membuat harga mie ayam dan bensin naik. Kedua indikator ini memengaruhi daya beli."}'::jsonb, 'advanced', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'macro-indicators'), 'explanation', '{"text": "Indikator makro seperti BI Rate, inflasi, dan nilai tukar memengaruhi ekonomi secara keseluruhan dan berdampak pada investasi serta daya beli."}'::jsonb, 'advanced', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'macro-indicators'), 'explanation', '{"text": "Investor pemula tidak perlu mencoba menaklukkan indikator makro. Yang bisa dikontrol adalah tujuan, diversifikasi, dan disiplin menabung."}'::jsonb, 'advanced', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'macro-indicators'), 'question', '{"type": "matching", "question": "Pasangkan indikator makro dengan dampaknya.", "pairs": [["BI Rate naik", "Bunga tabungan/deposito cenderung naik"], ["Inflasi tinggi", "Daya beli uang menurun"], ["Rupiah melemah", "Harga barang impor cenderung naik"]], "answer": {"BI Rate naik": "Bunga tabungan/deposito cenderung naik", "Inflasi tinggi": "Daya beli uang menurun", "Rupiah melemah": "Harga barang impor cenderung naik"}, "explanation": "Indikator makro saling terkait dan memengaruhi keuangan pribadi.", "difficulty": "advanced"}'::jsonb, 'advanced', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'macro-indicators'), 'question', '{"type": "multiple_choice", "question": "Mengapa investor pemula tidak perlu mencoba ''timing'' indikator makro?", "options": ["Karena sulit diprediksi secara konsisten", "Karena indikator makro tidak penting", "Karena hanya bank yang terpengaruh", "Karena indikator makro tidak berubah"], "answer": "Karena sulit diprediksi secara konsisten", "explanation": "Tidak ada yang secara konsisten memprediksi pergerakan makro; fokus pada yang bisa dikontrol.", "difficulty": "advanced"}'::jsonb, 'advanced', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'macro-indicators'), 'question', '{"type": "true_false", "question": "Inflasi tinggi selalu meningkatkan daya beli uang.", "answer": false, "explanation": "Inflasi tinggi menggerus daya beli karena harga barang naik.", "difficulty": "advanced"}'::jsonb, 'advanced', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'macro-indicators'), 'question', '{"type": "fill_blank", "question": "Bank Indonesia mengatur suku bunga acuan yang disebut _____ Rate.", "answer": "BI", "explanation": "BI Rate adalah suku bunga acuan yang memengaruhi bunga pinjaman dan tabungan.", "difficulty": "advanced"}'::jsonb, 'advanced', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'behavioral-bias-intro'), 'example', '{"text": "Semua teman Bayu membeli saham GOTO karena viral di TikTok. Bayu takut ketinggalan (FOMO) dan ingin membeli juga, meski tidak tahu fundamental perusahaannya. Di saat yang sama, ia takut rugi (loss aversion). Kedua bias ini mengaburkan pertimbangannya."}'::jsonb, 'advanced', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'behavioral-bias-intro'), 'example', '{"text": "Rina melihat sahamnya turun 5%. Karena takut rugi lebih besar, ia langsung menjual. Padahal tujuannya investasi jangka panjang dan penurunan itu normal. Loss aversion membuatnya bereaksi berlebihan."}'::jsonb, 'advanced', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'behavioral-bias-intro'), 'explanation', '{"text": "Bias perilaku adalah pola pikir yang menyimpangkan keputusan keuangan. Contohnya FOMO, loss aversion, dan herd behavior (mengikuti kerumunan)."}'::jsonb, 'advanced', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'behavioral-bias-intro'), 'explanation', '{"text": "Mengenali bias membantu kita membuat keputusan lebih tenang. Caranya: kembali ke tujuan awal, lakukan riset, dan hindari keputusan besar saat emosi tinggi."}'::jsonb, 'advanced', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'behavioral-bias-intro'), 'question', '{"type": "case_study", "question": "Baca kasus berikut dan pilih respons terbaik.", "caseText": "Bayu melihat semua temannya membeli saham GOTO karena viral di TikTok. Ia takut ketinggalan untung, tetapi juga takut kehilangan uang. Ia belum memahami bisnis perusahaan.", "followUp": {"question": "Bias apa yang dominan pada Bayu?", "options": ["FOMO dan loss aversion", "Tidak ada bias", "Keputusan rasional murni", "Diversifikasi berlebihan"], "answer": "FOMO dan loss aversion", "explanation": "Bayu termakan tren (FOMO) dan takut rugi (loss aversion), yang mengaburkan riset."}, "answer": "Bayu mengambil keputusan berdasarkan emosi, bukan analisis.", "explanation": "Bias perilaku bisa merusak rencana keuangan. Bayu sebaiknya kembali ke tujuan dan riset sebelum membeli saham.", "difficulty": "advanced"}'::jsonb, 'advanced', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'behavioral-bias-intro'), 'question', '{"type": "multiple_choice", "question": "Loss aversion adalah kecenderungan untuk ...", "options": ["Lebih takut rugi daripada senang untung", "Suka kehilangan uang", "Tidak peduli dengan kerugian", "Selalu membeli saham yang turun"], "answer": "Lebih takut rugi daripada senang untung", "explanation": "Loss aversion membuat kita merasakan penderitaan kerugian lebih besar daripada kegembiraan keuntungan.", "difficulty": "advanced"}'::jsonb, 'advanced', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'behavioral-bias-intro'), 'question', '{"type": "true_false", "question": "Mengikuti tren media sosial tanpa riset adalah contoh herd behavior yang sehat.", "answer": false, "explanation": "Herd behavior bisa berbahaya jika keputusan didasarkan pada FOMO, bukan analisis.", "difficulty": "advanced"}'::jsonb, 'advanced', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'behavioral-bias-intro'), 'question', '{"type": "fill_blank", "question": "FOMO adalah kepanjakan dari Fear Of Missing _____.", "answer": "Out", "explanation": "FOMO adalah takut ketinggalan kesempatan, yang sering mendorong keputusan impulsif.", "difficulty": "advanced"}'::jsonb, 'advanced', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'building-financial-plan'), 'example', '{"text": "Ani berusia 19 tahun, penghasilan Rp2,5 juta/bulan dari desain freelance, tanpa dana darurat, dan punya utang PayLater Rp2 juta. Rencananya: 1) buat dana darurat kecil, 2) bayar utang PayLater, 3) buat anggaran 50/30/20, 4) mulai asuransi kesehatan, 5) mulai investasi kecil."}'::jsonb, 'advanced', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'building-financial-plan'), 'example', '{"text": "Budi ingin memiliki rumah dalam 10 tahun. Ia membuat rencana: hitung kebutuhan dana, sisihkan setiap bulan, pilih instrumen investasi sesuai horizon, dan evaluasi setiap tahun."}'::jsonb, 'advanced', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'building-financial-plan'), 'explanation', '{"text": "Rencana keuangan mencakup tujuan, dana darurat, utang, proteksi, dan langkah investasi. Rencana membantu kita membuat keputusan yang selaras dengan tujuan jangka panjang."}'::jsonb, 'advanced', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'building-financial-plan'), 'explanation', '{"text": "Rencana keuangan tidak harus sempurna sejak awal. Mulailah sederhana, lalu evaluasi dan sesuaikan seiring perubahan penghasilan dan tujuan."}'::jsonb, 'advanced', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'building-financial-plan'), 'question', '{"type": "case_study", "question": "Baca kasus berikut dan pilih urutan langkah terbaik.", "caseText": "Ani, 19 tahun, penghasilan Rp2,5 juta/bulan, tidak punya dana darurat, punya utang PayLater Rp2 juta.", "followUp": {"question": "Langkah pertama apa yang paling penting?", "options": ["Buat dana darurat kecil dan hentikan pembelian baru", "Langsung investasi di saham", "Beli gadget baru untuk kerja", "Ajukan pinjaman baru untuk melunasi PayLater"], "answer": "Buat dana darurat kecil dan hentikan pembelian baru", "explanation": "Dana darurat kecil mencegah utang tambahan; menghentikan pembelian baru menghentikan spiral utang."}, "answer": "Prioritas pertama adalah proteksi dasar dan menghentikan spiral utang.", "explanation": "Rencana keuangan dimulai dari fondasi: dana darurat, utang, anggaran, proteksi, baru investasi.", "difficulty": "advanced"}'::jsonb, 'advanced', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'building-financial-plan'), 'question', '{"type": "ordering", "question": "Urutkan langkah menyusun rencana keuangan dasar.", "options": ["Tetapkan tujuan", "Siapkan dana darurat", "Lunasi utang berbunga tinggi", "Pilih instrumen investasi sesuai tujuan"], "answer": ["Tetapkan tujuan", "Siapkan dana darurat", "Lunasi utang berbunga tinggi", "Pilih instrumen investasi sesuai tujuan"], "explanation": "Mulai dari tujuan, lindungi dengan dana darurat, bebaskan dari utang berbunga tinggi, baru investasi.", "difficulty": "advanced"}'::jsonb, 'advanced', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'building-financial-plan'), 'question', '{"type": "true_false", "question": "Rencana keuangan hanya perlu dibuat sekali seumur hidup.", "answer": false, "explanation": "Rencana keuangan harus dievaluasi dan disesuaikan secara berkala.", "difficulty": "advanced"}'::jsonb, 'advanced', TRUE),
  (gen_random_uuid(), (SELECT id FROM lessons WHERE slug = 'building-financial-plan'), 'question', '{"type": "fill_blank", "question": "Sebelum berinvestasi, pastikan dana darurat sudah tersedia dan utang _____ sudah terkendali.", "answer": "berbunga tinggi", "explanation": "Utang berbunga tinggi bisa menghapus keuntungan investasi, sehingga perlu dikendalikan terlebih dahulu.", "difficulty": "advanced"}'::jsonb, 'advanced', TRUE);
